package e.e.a;
import java.io.*;import java.net.*;import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.AtomicInteger;
public final class StorageImprovementsTest {
 static void check(boolean b,String s){if(!b)throw new AssertionError(s);}
 static DirectoryIndex.Item<String> file(String name,String parent){return new DirectoryIndex.Item<>(name,parent+"/"+name,false,42,100);}
 public static void main(String[] args)throws Exception{
  long bytes=PlanFetch250.bytes(new URL("https://example.test/v.m3u8"),u->"#EXTM3U\n#EXT-X-BYTERANGE:100@0\nv.mp4\n#EXT-X-BYTERANGE:100\nv.mp4\n#EXT-X-BYTERANGE:100\nv.mp4\n");check(bytes==300,"implicit offsets count distinct segments");
  for(String range:new String[]{"-1@0","10@-1","9223372036854775807@1","bad"})try{PlanFetch250.bytes(new URL("https://example.test/v.m3u8"),u->"#EXTM3U\n#EXT-X-BYTERANGE:"+range+"\nv.mp4\n");throw new AssertionError("accepted malformed range");}catch(IOException expected){}
  for(String json:new String[]{"{\"folders\":[null]}","{\"videos\":[1]}","{\"folders\":\"wrong\"}","{\"folders\":[{\"id\":1,\"name\":\"A\"}]}","{\"videos\":[{\"id\":\"x\",\"videoId\":\"sm1\",\"url\":\"sm1\",\"folder\":\"missing\"}]}"})try{new LocalPlaylistData(json);throw new AssertionError("malformed store accepted");}catch(org.json.JSONException expected){}
  class Store implements PlaylistStorage.Persistence {String value="{}";boolean fail;int writes;public String read(){return value;}public boolean write(String s){value=s;writes++;return !fail;}public void restore(String s){value=s;}}
  Store store=new Store();ExecutorService pool=Executors.newFixedThreadPool(4);try{List<Future<?>> pending=new ArrayList<>();for(int n=0;n<100;n++){final int number=n;pending.add(pool.submit(()->{try{check(PlaylistStorage.update(store,d->d.folder("Folder "+number)),"saved");}catch(Exception e){throw new RuntimeException(e);}}));}for(Future<?> f:pending)f.get();check(new LocalPlaylistData(store.value).folders.length()==100,"queued edits do not overwrite one another");String before=store.value;store.fail=true;check(!PlaylistStorage.update(store,d->d.folder("Lost"))&&before.equals(store.value),"failed persistence restores original memory snapshot");store.value="{\"folders\":[null]}";before=store.value;int count=store.writes;try{PlaylistStorage.update(store,d->d.folder("Other"));throw new AssertionError();}catch(org.json.JSONException expected){}check(before.equals(store.value)&&count==store.writes,"invalid snapshot is preserved without a write");}finally{pool.shutdownNow();}
  class Provider implements DirectoryIndex.Provider<String> {
   long now;final Map<String,Integer> queries=new ConcurrentHashMap<>();final Map<String,List<DirectoryIndex.Item<String>>> files=new ConcurrentHashMap<>();CountDownLatch entered,release;int metadata;
   Provider(){List<DirectoryIndex.Item<String>> dirs=new ArrayList<>();for(int n=0;n<1000;n++){String id="sm"+n;dirs.add(new DirectoryIndex.Item<>(id,id,true,0,0));files.put(id,new ArrayList<>(Arrays.asList(file(id+".json",id),file(id+".complete",id))));}dirs.add(file("sm2000.json","root"));files.put("root",dirs);}
   public List<DirectoryIndex.Item<String>> children(String p)throws IOException{queries.merge(p,1,Integer::sum);if(p.equals("sm0")&&entered!=null){entered.countDown();try{if(!release.await(3,TimeUnit.SECONDS))throw new IOException("blocked");}catch(InterruptedException e){throw new IOException(e);}}return new ArrayList<>(files.get(p));}
   public String create(String p,String n,boolean d){String ref=p+"/"+n;files.get(p).add(new DirectoryIndex.Item<>(n,ref,d,0,0));if(d)files.put(ref,new ArrayList<>());return ref;}
   public DirectoryIndex.Item<String> stat(String r,String n){metadata++;return new DirectoryIndex.Item<>(n,r,false,99,200);}
   public long now(){return now;}
  }
  Provider provider=new Provider();DirectoryIndex<String> index=new DirectoryIndex<>("root",provider);
  check(index.document("sm1.mp4",false).equals("sm1/sm1.complete"),"completion marker alias");for(int n=0;n<100;n++)check(index.stat("sm1.json").size==42,"cached metadata");check(provider.queries.get("root")==1&&provider.queries.get("sm1")==1&&provider.queries.size()==2,"single video lookup does not scan 999 unrelated folders");
  index.changed("sm1.json");check(index.stat("sm1.json").size==99&&provider.metadata==1,"write invalidation reloads only target metadata");index.stat("sm1.json");check(provider.metadata==1,"metadata reused after refresh");check(index.document("sm2000.json",false).equals("root/sm2000.json"),"legacy flat files remain readable");
  provider.now=2001;index.stat("sm1.json");check(provider.queries.get("root")==2&&provider.queries.get("sm1")==2,"expiry still targets a single directory");
  provider.entered=new CountDownLatch(1);provider.release=new CountDownLatch(1);ExecutorService readers=Executors.newFixedThreadPool(2);try{Future<?> slow=readers.submit(()->{try{index.stat("sm0.json");}catch(Exception e){throw new RuntimeException(e);}});check(provider.entered.await(1,TimeUnit.SECONDS),"slow provider entered");Future<?> fast=readers.submit(()->{try{check(index.stat("sm2.json")!=null,"other directory readable");}catch(Exception e){throw new RuntimeException(e);}});fast.get(1,TimeUnit.SECONDS);provider.release.countDown();slow.get();}finally{provider.release.countDown();readers.shutdownNow();}
  String made=index.document("sm3000.json",true);check(made!=null&&index.document("sm3000.json",false).equals(made),"new directory and document remembered");index.forget("sm3000.json");check(index.document("sm3000.json",false)==null,"deleted document invalidated");
  DurationRangeModel range=new DurationRangeModel(0,900,false);range.typed(600,900);range.dragged(range.low,1200);check(range.low==600&&range.high==1200,"typed minimum survives dragging maximum");range.unlimited=true;range.typed(1800,range.high);check(range.maximum()==0&&range.high>=range.low,"unlimited retains typed minimum");range.unlimited=false;check(range.maximum()==1800,"finite range restored consistently");
  System.out.println("Storage improvements: failure preservation, concurrent edits, malformed snapshots, implicit ranges, scoped queries, concurrent providers and shared duration state passed");
 }
}
